class Solution {
public:
    int concatenatedBinary(int n) {
        long long MOD = 1e9 + 7;
        long long ans = 0;
        int bit_len = 0;
        for (int i = 1; i <= n; ++i) {
            if ((i & (i - 1)) == 0) bit_len++;
            ans = ((ans << bit_len) | i) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int concatenatedBinary(int n) {
        long MOD = 1000000007L;
        long ans = 0;
        int bitLen = 0;
        for (int i = 1; i <= n; ++i) {
            if ((i & (i - 1)) == 0) bitLen++;
            ans = ((ans << bitLen) | i) % MOD;
        }
        return (int)ans;
    }
}

/**
 * @param {number} n
 * @return {number}
 */
var concatenatedBinary = function(n) {
    const MOD = 1000000007n;
    let ans = 0n;
    let bitLen = 0n;
    for (let i = 1n; i <= BigInt(n); ++i) {
        if ((i & (i - 1n)) === 0n) bitLen++;
        ans = ((ans << bitLen) | i) % MOD;
    }
    return Number(ans);
};
